"""Shared websocket handling for the Deepgram ASR engines."""

import json
import os
from abc import ABC, abstractmethod
from typing import Any, Generic, Optional, TypeVar

import structlog
import websockets.exceptions
from websockets.asyncio.client import ClientConnection, connect

from rasa.core.channels.voice_stream.asr.asr_engine import ASREngine
from rasa.core.channels.voice_stream.asr.asr_event import ASREvent
from rasa.core.channels.voice_stream.audio_bytes import (
    L16_16KHZ,
    L16_24KHZ,
    L16_48KHZ,
    MULAW_8KHZ,
    AudioFormat,
    RasaAudioBytes,
)
from rasa.shared.constants import DEEPGRAM_API_KEY_ENV_VAR

from .config import DeepgramASRConfigBase

logger = structlog.get_logger(__name__)

ConfigT = TypeVar("ConfigT", bound=DeepgramASRConfigBase)


class _DeepgramASRBase(ASREngine[ConfigT], Generic[ConfigT], ABC):
    """Common websocket handling for the Deepgram ASR engines."""

    required_env_vars = (DEEPGRAM_API_KEY_ENV_VAR,)
    api_version: str

    @abstractmethod
    def _get_query_params(self) -> str:
        """Return the URL-encoded query parameters for this engine."""

    @abstractmethod
    def engine_event_to_asr_event(self, event: Any) -> Optional[ASREvent]:
        """Translate one provider message into a Rasa ASR event."""

    async def open_websocket_connection(self) -> ClientConnection:
        """Connect to the configured Deepgram websocket endpoint."""
        api_key = os.environ[DEEPGRAM_API_KEY_ENV_VAR]
        headers = {"Authorization": f"Token {api_key}"}
        url = self._get_api_url() + self._get_query_params()
        try:
            return await connect(url, additional_headers=headers)
        except websockets.exceptions.InvalidStatus as error:
            if error.response.status_code == 401:
                message = "Please make sure your Deepgram API key is correct."
            else:
                message = "Connection to Deepgram failed."
            logger.error(
                "deepgram.connection.failed",
                status_code=error.response.status_code,
                error=message,
                url=url,
            )
            raise

    def _get_api_url(self) -> str:
        """Build the base websocket URL for this engine's API version."""
        return f"wss://{self.config.endpoint}/{self.api_version}/listen?"

    async def signal_audio_done(self) -> None:
        """Tell Deepgram that no more audio will be sent."""
        if self.asr_socket is None:
            raise AttributeError("Websocket not connected.")
        await self.asr_socket.send(json.dumps({"type": "CloseStream"}))

    def rasa_audio_bytes_to_engine_bytes(self, chunk: RasaAudioBytes) -> bytes:
        """Convert Rasa audio bytes to the raw bytes expected by Deepgram."""
        return chunk.data

    async def send_keep_alive(self) -> None:
        """Send a keep-alive message when supported by the API version."""

    @staticmethod
    def _encoding_for(audio_format: AudioFormat) -> str:
        """Return the Deepgram encoding string for a supported audio format."""
        if audio_format in (L16_16KHZ, L16_24KHZ, L16_48KHZ):
            return "linear16"
        if audio_format == MULAW_8KHZ:
            return "mulaw"
        raise ValueError(f"Unsupported audio format: {audio_format}")
